package app

import (
	"context"
	"crypto/tls"
	_ "embed"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"time"
)

const (
	defaultReadTimeout  = 10 * time.Second
	defaultWriteTimeout = 15 * time.Second
	defaultIdleTimeout  = 120 * time.Second
)

// The development certificate is generated by "make ensure_dev_certs" (gitignored) and used
// only with env dev; see loadTLSCert.
//
//go:embed certs/dev_cert.pem
var embeddedCertFile []byte

//go:embed certs/dev_key.pem
var embeddedKeyFile []byte

// newTLSConfig serves cert with TLS 1.3 only. Every caller in this setup (browsers, Node-RED on
// Node 20, curl) speaks it, and 1.3 leaves no cipher suite to choose badly.
func newTLSConfig(cert tls.Certificate) *tls.Config {
	return &tls.Config{
		Certificates: []tls.Certificate{cert},
		MinVersion:   tls.VersionTLS13,
	}
}

// StartWebServer initializes and starts the HTTPS server asynchronously.
// - Production: uses file-based cert/key from config
// - Development fallback: embedded self-signed cert
// - Non-blocking: runs in goroutine
// - Graceful shutdown on app.ctx cancellation
func (app *App) StartWebServer() error {
	// Set default timeouts
	app.web.ReadTimeout = defaultReadTimeout
	app.web.WriteTimeout = defaultWriteTimeout
	app.web.IdleTimeout = defaultIdleTimeout

	// Load TLS certificate
	cert, err := loadTLSCert(app.config.Webserver.CertFile, app.config.Webserver.KeyFile, app.config.Env)
	if err != nil {
		return fmt.Errorf("failed to load TLS certificate: %w", err)
	}

	app.web.TLSConfig = newTLSConfig(cert)

	// Create listener
	listener, err := net.Listen("tcp", app.web.Addr)
	if err != nil {
		return fmt.Errorf("failed to create listener: %w", err)
	}

	// Channel to report server runtime errors
	serverErrCh := make(chan error, 1)

	go func() {
		// ServeTLS blocks until Shutdown is called
		err := app.web.ServeTLS(listener, "", "")
		if err != nil && !errors.Is(err, http.ErrServerClosed) {
			serverErrCh <- err
		}

		// Close the listener when ServeTLS exits, but ignore the normal
		// already-closed case during graceful shutdown.
		if err := listener.Close(); err != nil && !errors.Is(err, net.ErrClosed) {
			slog.Error("Failed to close listener", "error", err)
		}
	}()

	// Goroutine to monitor runtime errors and handle shutdown
	app.wg.Go(func() {

		select {
		case err := <-serverErrCh:
			slog.Error("Webserver runtime error", "error", err)
			// The signal handler restarts the App; it waits for this goroutine via app.wg.
			select {
			case app.serverErr <- err:
			default:
			}
		case <-app.ctx.Done():
			ctxShutdown, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			if err := app.web.Shutdown(ctxShutdown); err != nil {
				slog.Error("Failed to shutdown webserver gracefully", "error", err)
			} else {
				slog.Info("Webserver stopped gracefully")
			}
		}
	})

	return nil
}

// loadTLSCert loads the file-based certificate. Only with env dev it falls back to the embedded
// development certificate when certFile does not exist: its key ships in every release.
func loadTLSCert(certFile, keyFile, env string) (tls.Certificate, error) {
	if _, err := os.Stat(certFile); err == nil {
		return tls.LoadX509KeyPair(certFile, keyFile)
	} else if errors.Is(err, os.ErrNotExist) {
		if env == ProdEnv {
			return tls.Certificate{}, fmt.Errorf("certFile %s not found; the embedded development certificate is not used with env: %s", certFile, ProdEnv)
		}
		slog.Warn("TLS cert file not found, using embedded fallback", "certFile", certFile, "env", env)
		return tls.X509KeyPair(embeddedCertFile, embeddedKeyFile)
	} else {
		return tls.Certificate{}, fmt.Errorf("failed to read cert file: %w", err)
	}
}
